const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, BorderStyle,
  AlignmentType, Table, TableRow, TableCell, WidthType, ShadingType,
  UnderlineType
} = require("docx");

const NAVY = "1F3A5F";
const GRAY = "555555";
const LIGHT_LINE = "BFBFBF";

const nameRun = new TextRun({ text: "JAVIER MALPICA HERRERA", bold: true, size: 40, color: NAVY, font: "Calibri" });
const titleRun = new TextRun({ text: "Gerente Comercial | Última Milla, 3PL & Logística B2B | Liderazgo de Equipos de Venta", size: 22, color: GRAY, font: "Calibri" });

const contactRun = new TextRun({
  text: "55 4370 6645  |  javmalher@gmail.com  |  linkedin.com/in/javier-malpica  |  Tlalnepantla, Estado de México",
  size: 19, color: GRAY, font: "Calibri"
});

function sectionHeading(text) {
  return new Paragraph({
    spacing: { before: 260, after: 100 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: NAVY, space: 2 } },
    children: [ new TextRun({ text: text.toUpperCase(), bold: true, size: 22, color: NAVY, font: "Calibri" }) ]
  });
}

function jobHeading(role, dates) {
  return new Paragraph({
    spacing: { before: 180, after: 20 },
    tabStops: [{ type: "right", position: 9350 }],
    children: [
      new TextRun({ text: role, bold: true, size: 21, font: "Calibri" }),
      new TextRun({ text: `\t${dates}`, italics: true, size: 19, color: GRAY, font: "Calibri" })
    ]
  });
}

function companyLine(text) {
  return new Paragraph({
    spacing: { after: 60 },
    children: [ new TextRun({ text, size: 20, italics: true, color: NAVY, font: "Calibri" }) ]
  });
}

function bullet(text) {
  return new Paragraph({
    spacing: { after: 40 },
    bullet: { level: 0 },
    children: [ new TextRun({ text, size: 20, font: "Calibri" }) ]
  });
}

function bodyParagraph(text) {
  return new Paragraph({
    spacing: { after: 100 },
    children: [ new TextRun({ text, size: 20, font: "Calibri" }) ]
  });
}

function skillLine(label, text) {
  return new Paragraph({
    spacing: { after: 60 },
    children: [
      new TextRun({ text: `${label}: `, bold: true, size: 20, font: "Calibri" }),
      new TextRun({ text, size: 20, font: "Calibri" })
    ]
  });
}

function eduLine(text) {
  return new Paragraph({
    spacing: { after: 60 },
    bullet: { level: 0 },
    children: [ new TextRun({ text, size: 20, font: "Calibri" }) ]
  });
}

const doc = new Document({
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 720, bottom: 720, left: 900, right: 900 }
      }
    },
    children: [
      new Paragraph({ alignment: AlignmentType.LEFT, spacing: { after: 40 }, children: [nameRun] }),
      new Paragraph({ alignment: AlignmentType.LEFT, spacing: { after: 80 }, children: [titleRun] }),
      new Paragraph({
        alignment: AlignmentType.LEFT,
        spacing: { after: 0 },
        border: { bottom: { style: BorderStyle.SINGLE, size: 10, color: NAVY, space: 6 } },
        children: [contactRun]
      }),

      sectionHeading("Perfil Profesional"),
      bodyParagraph("Líder comercial B2B/B2C con más de 8 años de experiencia en logística de última milla, transporte terrestre y soluciones 3PL/4PL en México. Actualmente lidero un equipo de 6 Sales Managers en iMile Delivery, gestionando un pipeline de más de $150 millones de pesos con 200+ cuentas AAA. Track record comprobado de cierres de hasta $50 MDP mensuales, apertura de nuevas zonas de negocio (más de $30 MDP mensuales estructurados) y crecimiento de +316% en facturación regional. Experiencia negociando con tomadores de decisión de cuentas como Walmart, Liverpool, Amazon, Mercado Libre, Palacio de Hierro y Envia.com. Fortalezas: apertura de mercados, venta consultiva multi-stakeholder y presentación de resultados a nivel dirección."),

      sectionHeading("Experiencia Profesional"),

      jobHeading("Commercial Team Lead", "Octubre 2025 – Actualidad"),
      companyLine("iMile Delivery México"),
      bullet("Lidero un equipo comercial de 6 Sales Managers: definición de objetivos, seguimiento de pipeline, coaching comercial y mejora de proceso de venta."),
      bullet("Gestiono un pipeline de más de $150 MDP con 200+ cuentas AAA de los sectores eCommerce, fintech, retail y moda."),
      bullet("Cierre de contratos por hasta $50 millones de pesos mensuales, con ticket promedio optimizado a ~$80 por envío frente a la competencia."),
      bullet("Diseño y ejecuto la estrategia de prospección de cuentas eCommerce/D2C de 500 a 10,000 pedidos/día en CDMX, EdoMex, Puebla, Guadalajara y Monterrey."),
      bullet("Apoyo el cierre de negociaciones complejas multi-stakeholder (logística, operaciones, compras, dirección) y expando volumen vía cross-selling."),
      bullet("Presento resultados y avance de pipeline directamente al Director Comercial y CEO; construyo argumentos de valor diferenciados vs. Estafeta con base en KPIs de servicio (>98.5% de éxito, <0.01% de daños)."),

      jobHeading("Gerente Comercial – Desarrollo de Nuevo Negocio y Retornos", "Junio 2025 – Octubre 2025"),
      companyLine("OPL Logística del Valle de México · Nacional"),
      bullet("Diseñé e implementé la estrategia comercial para atraer nuevos clientes y optimizar viajes de retorno en rutas nacionales clave."),
      bullet("Reduje costos logísticos y aumenté la rentabilidad negociando viajes de retorno; recuperé y amplié cartera estratégica."),
      bullet("Elaboré propuestas competitivas en unidades de 1.5 a 53 pies (seco y refrigerado) para sectores Pharma, 3PL, 4PL y cuentas AAA."),

      jobHeading("Gerente Regional Comercial", "Mayo 2024 – Abril 2025"),
      companyLine("Estafeta · Edo. Méx. / Morelos / Guerrero"),
      bullet("Incrementé +316.67% la facturación mensual en 1 año, gestionando un ticket promedio de ~$140 por envío."),
      bullet("Desarrollé la estrategia comercial regional; lideré selección, contratación, formación y desarrollo del equipo comercial."),
      bullet("Gestión de cuentas clave, negociación y cierre de acuerdos; resolución de incidencias y reclamaciones."),
      bullet("Up-selling y cross-selling en última y primera milla, logística terrestre, FFWD y 3PL."),

      jobHeading("Key Account Manager Sr.", "Mayo 2020 – Abril 2024"),
      companyLine("Transportes LIPU / Traxion · CDMX / Edo. Méx."),
      bullet("Aperturé y desarrollé nuevas zonas de negocio, estructurando cuentas por más de $30 MDP mensuales."),
      bullet("Gestioné cuentas de alto perfil: Walmart, Liverpool, Mercado Libre, Amazon, Palacio de Hierro, Envia.com y Tendencys."),
      bullet("Prospección de nuevos clientes, recuperación de cartera vencida y cross/up-selling sobre cuentas existentes."),
      bullet("Negociación, revisión de contratos, cierre de venta y supervisión del arranque de nuevos proyectos."),

      jobHeading("Commercial Executive Senior", "Febrero 2017 – Abril 2020"),
      companyLine("Grupo Pissa – Soluciones Integrales en Tecnología · CDMX / Edo. Méx."),
      bullet("Prospección de clientes en frío y desarrollo de nuevas oportunidades de negocio."),
      bullet("Cierre de proyectos con unidades de negocio internas; propuse mejoras a procesos de compras y licitaciones."),

      sectionHeading("Formación Académica"),
      eduLine("Maestría en Dirección y Estrategias Comerciales — UNIR (Sep 2024 – Actualidad)"),
      eduLine("Diplomado en Gestión Logística — Universidad del Valle de México (Sep 2025 – Actualidad)"),
      eduLine("Licenciatura en Derecho — Universidad Tecnológica de México (Dic 2017)"),

      sectionHeading("Habilidades y Herramientas"),
      skillLine("Comercial", "venta consultiva B2B/B2C, SPIN Selling, prospección, Key Account Management, apertura de mercados, negociación multi-stakeholder."),
      skillLine("Logística", "última y primera milla, 3PL/4PL, FFWD, paquetería, LTL/FTL, transporte terrestre."),
      skillLine("Herramientas", "Salesforce, SAP, CRM corporativo, Microsoft Office."),
      skillLine("Idiomas", "Español (nativo), Inglés (intermedio). Formación online continua en ventas (30+ cursos)."),
    ]
  }]
});

Packer.toBuffer(doc).then(buf => {
  require("fs").writeFileSync("/home/claude/cv/CV_Javier_Malpica_Herrera_2026.docx", buf);
  console.log("done");
});

