const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
        AlignmentType, LevelFormat, BorderStyle, WidthType, ShadingType,
        HeadingLevel } = require('docx');
const fs = require('fs');

const NAVY = "1F3864";
const ACCENT = "2E75B6";
const GRAY = "595959";
const LIGHT_GRAY = "808080";

const PAGE_WIDTH = 12240;
const MARGIN = 1080; // 0.75"
const CONTENT_WIDTH = PAGE_WIDTH - (MARGIN * 2);

function sectionHeading(text) {
  return new Paragraph({
    spacing: { before: 280, after: 120 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: ACCENT, space: 4 } },
    children: [
      new TextRun({ text: text.toUpperCase(), bold: true, color: NAVY, size: 23, font: "Calibri" })
    ]
  });
}

function jobHeader(title, company, dates) {
  return new Paragraph({
    spacing: { before: 200, after: 20 },
    tabStops: [{ type: "right", position: CONTENT_WIDTH }],
    children: [
      new TextRun({ text: title, bold: true, size: 22, color: "1A1A1A", font: "Calibri" }),
      new TextRun({ text: `\t${dates}`, italics: true, size: 19, color: LIGHT_GRAY, font: "Calibri" })
    ]
  });
}

function companyLine(company) {
  return new Paragraph({
    spacing: { after: 80 },
    children: [
      new TextRun({ text: company, bold: true, size: 20, color: ACCENT, font: "Calibri" })
    ]
  });
}

function bullet(text) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    spacing: { after: 60 },
    children: [ new TextRun({ text, size: 20, color: "262626", font: "Calibri" }) ]
  });
}

function bodyText(text) {
  return new Paragraph({
    spacing: { after: 100 },
    children: [ new TextRun({ text, size: 20, color: "262626", font: "Calibri" }) ]
  });
}

const doc = new Document({
  numbering: {
    config: [
      { reference: "bullets",
        levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 260, hanging: 220 } } } }] },
    ]
  },
  styles: {
    default: { document: { run: { font: "Calibri", size: 20 } } }
  },
  sections: [{
    properties: {
      page: {
        size: { width: PAGE_WIDTH, height: 15840 },
        margin: { top: MARGIN, right: MARGIN, bottom: MARGIN, left: MARGIN }
      }
    },
    children: [
      // HEADER
      new Paragraph({
        alignment: AlignmentType.LEFT,
        spacing: { after: 40 },
        children: [
          new TextRun({ text: "JAVIER MALPICA HERRERA", bold: true, size: 36, color: NAVY, font: "Calibri" })
        ]
      }),
      new Paragraph({
        spacing: { after: 200 },
        children: [
          new TextRun({ text: "Commercial Team Lead | Last Mile & 3PL Logistics | B2B Sales & Key Accounts", size: 22, color: GRAY, italics: true, font: "Calibri" })
        ]
      }),
      new Paragraph({
        spacing: { after: 240 },
        border: { bottom: { style: BorderStyle.SINGLE, size: 16, color: NAVY, space: 6 } },
        children: [
          new TextRun({ text: "55 4370 6645   |   javmalher@gmail.com   |   linkedin.com/in/javier-malpica   |   Tlalnepantla, Estado de México", size: 18, color: GRAY, font: "Calibri" })
        ]
      }),

      // PERFIL PROFESIONAL
      sectionHeading("Perfil Profesional"),
      bodyText("Líder comercial B2B con más de 6 años de experiencia en logística de última milla, transporte terrestre y soluciones 3PL/4PL en México. Actualmente lidero un equipo de 6 Sales Managers en iMile Delivery México, impulsando la prospección activa, el desarrollo de nuevo negocio y el crecimiento de cuentas estratégicas en el sector eCommerce. Track record comprobado en apertura de mercados, negociación con tomadores de decisión multi-stakeholder, cierre de acuerdos de alto valor y presentación de resultados a nivel dirección. Experiencia directa en carriers de talla nacional (Estafeta, Traxion/Transportes LIPU) y vocación por construir negocio en entornos de alto crecimiento."),

      // EXPERIENCIA
      sectionHeading("Experiencia Profesional"),

      jobHeader("Commercial Team Lead", "", "Octubre 2025 – Actualidad"),
      companyLine("iMile Delivery México"),
      bullet("Lidero un equipo comercial de 6 Sales Managers, definiendo objetivos, dando seguimiento a pipeline y asegurando el cumplimiento de metas de prospección y cierre."),
      bullet("Diseño y ejecuto la estrategia de prospección activa y desarrollo de nuevo negocio, identificando cuentas eCommerce y D2C con volumen de 100 a 10,000 pedidos/día en CDMX, EdoMex, Puebla, Guadalajara y Monterrey."),
      bullet("Apoyo directamente al equipo en el cierre de negociaciones complejas con múltiples stakeholders (logística, operaciones, compras, dirección), incluyendo cuentas de los sectores financiero, retail y moda."),
      bullet("Impulso el crecimiento de cuentas existentes mediante estrategias de cross-selling y expansión de volumen, fortaleciendo relaciones comerciales de largo plazo."),
      bullet("Presento resultados comerciales, avance de pipeline y análisis de mercado de forma periódica al Director Comercial y CEO, alineando la estrategia regional con los objetivos de la compañía."),
      bullet("Desarrollo argumentos de valor diferenciados frente a la competencia (Estafeta, paqueterías tradicionales), basados en KPIs de servicio: entregas de 1 a 2.3 días, tasa de éxito superior a 98.5% y tasa de daños/pérdidas menor a 0.01%."),

      jobHeader("Gerente Comercial – Desarrollo de Nuevo Negocio y Retornos", "", "Julio 2025 – Octubre 2025"),
      companyLine("OPL Logística de Valle de México · Nacional"),
      bullet("Diseñé e implementé la estrategia comercial para atraer nuevos clientes y optimizar viajes de retorno en rutas nacionales clave."),
      bullet("Incrementé la eficiencia operativa negociando viajes de retorno, reduciendo costos logísticos y aumentando la rentabilidad."),
      bullet("Gestioné y amplié la cartera de clientes estratégicos, fortaleciendo relaciones comerciales de largo plazo y recuperando cartera perdida."),
      bullet("Elaboré propuestas comerciales competitivas basadas en análisis de mercado y necesidades del cliente, en unidades de 1.5 a 53 pies, seco y refrigerado, para sectores Pharma, 3PL, 4PL y empresas AAA."),

      jobHeader("Gerente Regional Comercial", "", "Julio 2024 – Abril 2025"),
      companyLine("Estafeta · Edo. Méx. / Morelos / Guerrero"),
      bullet("Desarrollé la estrategia comercial regional, analizando el mercado local y definiendo objetivos de venta y expansión."),
      bullet("Lideré la selección, contratación, formación y desarrollo del equipo comercial de la región."),
      bullet("Gestioné cuentas clave, negociación y cierre de acuerdos, y resolución de incidencias y reclamaciones de clientes."),
      bullet("Impulsé estrategias de up-selling y cross-selling en servicios de última y primera milla, logística terrestre, FFWD y 3PL."),

      jobHeader("Key Account Manager Sr.", "", "Mayo 2020 – Abril 2024"),
      companyLine("Transportes LIPU / Traxion · CDMX / Edo. Méx."),
