const {
  Document, Packer, Paragraph, TextRun, AlignmentType, HeadingLevel,
  BorderStyle, TabStopType, TabStopPosition
} = require("docx");
const fs = require("fs");

const FONT = "Arial";
const BLUE = "1F3864";
const GREY = "595959";

const doc = new Document({
  styles: {
    default: { document: { run: { font: FONT, size: 22, color: "262626" } } },
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1080, right: 1440, bottom: 1080, left: 1440 },
      },
    },
    children: [
      // Letterhead
      new Paragraph({
        children: [new TextRun({ text: "BASIL", bold: true, size: 36, color: BLUE })],
      }),
      new Paragraph({
        children: [new TextRun({ text: "[Razón social completa de Basil]", size: 18, color: GREY })],
        spacing: { after: 60 },
      }),
      new Paragraph({
        border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: BLUE, space: 1 } },
        spacing: { after: 240 },
        children: [new TextRun({ text: "" })],
      }),

      // Date / location
      new Paragraph({
        alignment: AlignmentType.RIGHT,
        spacing: { after: 360 },
        children: [new TextRun({ text: "Ciudad de México, a [día] de [mes] de [año]" })],
      }),

      // Subject
      new Paragraph({
        spacing: { after: 240 },
        children: [new TextRun({ text: "A QUIEN CORRESPONDA", bold: true })],
      }),

      new Paragraph({
        spacing: { after: 240 },
        children: [new TextRun({ text: "Asunto: Carta de recomendación — iMile Delivery México", bold: true, color: BLUE })],
      }),

      // Body
      new Paragraph({
        spacing: { after: 240 },
        children: [new TextRun({
          text: "Por medio de la presente, en mi carácter de [cargo del firmante, ej. Director de Operaciones / Gerente de Logística] de Basil, hago constar que nuestra empresa ha sostenido una relación comercial con iMile Delivery México desde [mes/año de inicio], utilizando sus servicios de logística de última milla para la distribución de nuestros pedidos de comercio electrónico en [ciudades/zonas atendidas, ej. CDMX, EdoMex, Guadalajara]."
        })],
      }),

      new Paragraph({
        spacing: { after: 240 },
        children: [new TextRun({
          text: "Durante este periodo, iMile se ha desempeñado como un socio logístico confiable, cumpliendo de manera consistente con los tiempos de entrega acordados y manteniendo niveles de servicio adecuados para las necesidades operativas de Basil. Entre los aspectos que destacamos de su servicio se encuentran:"
        })],
      }),

      bullet("Tiempos de entrega: [ej. entregas en 1 a 2.3 días hábiles en CDMX/EdoMex, según lo experimentado por Basil]."),
      bullet("Tasa de éxito en entregas: [indicar % o describir cualitativamente, ej. \"consistentemente alta\"]."),
      bullet("Cobertura geográfica: [zonas/estados donde Basil ha utilizado el servicio]."),
      bullet("Atención y soporte: [mencionar respuesta del equipo comercial/operativo de iMile, resolución de incidencias, etc.]."),
      bullet("Manejo de devoluciones / logística inversa: [si aplica]."),

      new Paragraph({
        spacing: { before: 120, after: 240 },
        children: [new TextRun({
          text: "En nuestra experiencia, iMile ha contribuido a [beneficio concreto para Basil, ej. mejorar la experiencia de entrega para nuestros clientes finales / reducir incidencias de paquetería / escalar nuestra operación de envíos] sin comprometer la calidad del servicio."
        })],
      }),

      new Paragraph({
        spacing: { after: 240 },
        children: [new TextRun({
          text: "Por lo anterior, recomendamos a iMile Delivery México como proveedor de servicios de última milla para empresas de comercio electrónico con necesidades de distribución similares a las nuestras."
        })],
      }),

      new Paragraph({
        spacing: { after: 240 },
        children: [new TextRun({
          text: "Quedamos a disposición para cualquier aclaración o referencia adicional relacionada con esta recomendación."
        })],
      }),

      new Paragraph({
        spacing: { before: 480, after: 60 },
        children: [new TextRun({ text: "Atentamente," })],
      }),

      new Paragraph({ spacing: { before: 480, after: 0 }, children: [new TextRun({ text: "_____________________________" })] }),
      new Paragraph({ spacing: { after: 0 }, children: [new TextRun({ text: "[Nombre completo del firmante]", bold: true })] }),
      new Paragraph({ spacing: { after: 0 }, children: [new TextRun({ text: "[Cargo del firmante]" })] }),
      new Paragraph({ spacing: { after: 0 }, children: [new TextRun({ text: "Basil" })] }),
      new Paragraph({ spacing: { after: 0 }, children: [new TextRun({ text: "[Correo de contacto] · [Teléfono de contacto]", color: GREY, size: 18 })] }),
    ],
  }],
});

function bullet(text) {
  return new Paragraph({
    spacing: { after: 80 },
    indent: { left: 360 },
    tabStops: [{ type: TabStopType.LEFT, position: 360 }],
    children: [new TextRun({ text: "•  " + text })],
  });
}

Packer.toBuffer(doc).then((buffer) => {
  fs.writeFileSync("/home/claude/carta/Carta_Recomendacion_Basil_iMile.docx", buffer);
  console.log("done");
});

